def summarize(rows):
    """
    Summarize revenue by region.

    Args:
        rows: A list of dicts, each with keys 'region' and 'revenue'
              (revenue can be numeric or a string representation of a number)

    Returns:
        A dict mapping region to total revenue as float,
        ignoring rows with missing or unparseable revenue.
    """
    result = {}

    for row in rows:
        # Check if row has required keys
        if 'region' not in row or 'revenue' not in row:
            continue

        region = row['region']
        revenue = row['revenue']

        # Try to parse revenue as a number
        try:
            if isinstance(revenue, (int, float)):
                revenue_value = float(revenue)
            elif isinstance(revenue, str):
                revenue_value = float(revenue.strip())
            else:
                continue
        except (ValueError, TypeError):
            # Skip rows with unparseable revenue
            continue

        # Accumulate revenue by region
        if region not in result:
            result[region] = 0.0
        result[region] += revenue_value

    return result

import pytest
from summarize import summarize


def test_summarize_basic():
    """Test basic summarization functionality."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South', 'revenue': 200},
        {'region': 'North', 'revenue': 150},
    ]
    result = summarize(rows)
    assert result == {'North': 250.0, 'South': 200.0}


def test_summarize_with_string_revenue():
    """Test with revenue as strings."""
    rows = [
        {'region': 'East', 'revenue': '100'},
        {'region': 'West', 'revenue': '200.5'},
    ]
    result = summarize(rows)
    assert result == {'East': 100.0, 'West': 200.5}


def test_summarize_missing_revenue():
    """Test that rows with missing revenue are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South'},  # Missing revenue
        {'region': 'North', 'revenue': 50},
    ]
    result = summarize(rows)
    assert result == {'North': 150.0}


def test_summarize_invalid_revenue():
    """Test that rows with unparseable revenue are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South', 'revenue': 'invalid'},
        {'region': 'North', 'revenue': 50},
    ]
    result = summarize(rows)
    assert result == {'North': 150.0}


def test_summarize_missing_region_key():
    """Test that rows without region key are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'revenue': 50},  # Missing region
        {'region': 'North', 'revenue': 50},
    ]
    result = summarize(rows)
    assert result == {'North': 150.0}


def test_summarize_empty_rows():
    """Test with empty input."""
    result = summarize([])
    assert result == {}


def test_summarize_all_invalid():
    """Test when all rows have invalid data."""
    rows = [
        {'region': 'North', 'revenue': 'invalid'},
        {'region': 'South', 'revenue': None},
    ]
    result = summarize(rows)
    assert result == {}


def test_summarize_whitespace_string_revenue():
    """Test with whitespace in string revenue."""
    rows = [
        {'region': 'East', 'revenue': ' 100 '},
    ]
    result = summarize(rows)
    assert result == {'East': 100.0}


def test_summarize_float_revenue():
    """Test with float revenue values."""
    rows = [
        {'region': 'North', 'revenue': 100.5},
        {'region': 'North', 'revenue': 200.25},
    ]
    result = summarize(rows)
    assert result == {'North': 300.75}


if __name__ == '__main__':
    pytest.main([__file__, '-v'])

